package kcp

import (
	"bytes"
	"encoding/binary"
	"errors"
	"io"
	"net"
	"sync"
	"sync/atomic"
	"time"
)

// MuxSide identifies which peer is using a mux session. Client streams use odd
// stream IDs while server streams use even stream IDs.
type MuxSide uint8

const (
	MuxSideClient MuxSide = iota
	MuxSideServer
)

const (
	MuxPriorityHigh uint8 = iota
	MuxPriorityNormal
	MuxPriorityLow
)

const (
	defaultMuxMaxFrameSize = 16 * 1024
	defaultMuxSendWindow   = 1024 * 1024
	defaultMuxRecvWindow   = 1024 * 1024

	// Keep an upper bound on one DATA frame so a corrupt peer cannot ask us to
	// allocate an arbitrarily large payload before flow-control checks run.
	muxMaxFrameSizeLimit = 1 << 30
)

const (
	muxFrameHeaderSize = 9

	muxFrameOpen uint8 = iota + 1
	muxFrameData
	muxFrameWindowUpdate
	muxFrameClose
)

var (
	errMuxNilConn       = errors.New("nil mux connection")
	errMuxInvalidConfig = errors.New("invalid mux config")
	errMuxProtocol      = errors.New("mux protocol error")
	errMuxFrameTooLarge = errors.New("mux frame too large")
	errMuxIDExhausted   = errors.New("mux stream id exhausted")
)

// MuxConfig configures a mux session.
type MuxConfig struct {
	Side         MuxSide
	MaxFrameSize int
	SendWindow   int
	RecvWindow   int
}

// DefaultMuxConfig returns the default mux configuration.
func DefaultMuxConfig() MuxConfig {
	return MuxConfig{
		Side:         MuxSideClient,
		MaxFrameSize: defaultMuxMaxFrameSize,
		SendWindow:   defaultMuxSendWindow,
		RecvWindow:   defaultMuxRecvWindow,
	}
}

type muxFrame struct {
	typ      uint8
	streamID uint32
	arg      uint32
	payload  []byte
}

// MuxSession multiplexes independent ordered streams over a single net.Conn.
type MuxSession struct {
	conn net.Conn
	cfg  MuxConfig

	mu   sync.Mutex
	cond *sync.Cond

	closed   bool
	closeOne sync.Once
	done     chan struct{}

	nextID uint32

	streams map[uint32]*MuxStream
	acceptQ []*MuxStream

	// Session control frames (OPEN and WINDOW_UPDATE) are always sent ahead of
	// stream DATA. CLOSE is stored in the owning stream queue so it cannot
	// overtake DATA previously accepted on the same ordered sub-stream; once it
	// reaches that queue's head it is scheduled before DATA from other streams.
	controlQ []muxFrame
}

// MuxStream is an independent ordered stream carried by a MuxSession.
type MuxStream struct {
	sess     *MuxSession
	id       uint32
	priority uint8

	// Serializes Write calls on this stream so the bytes accepted by one Write
	// call remain contiguous relative to other concurrent Write calls.
	writeMu sync.Mutex

	// All fields below are protected by sess.mu.
	sendCredit int64
	recvBuf    bytes.Buffer
	sendQ      []muxFrame

	localClosed  bool
	remoteClosed bool
	removed      bool

	readDeadline time.Time
}

// NewMuxSession creates a mux session over conn and starts background frame
// reader/writer goroutines. A nil cfg uses DefaultMuxConfig().
func NewMuxSession(conn net.Conn, cfg *MuxConfig) (*MuxSession, error) {
	if conn == nil {
		return nil, errMuxNilConn
	}

	c, err := normalizeMuxConfig(cfg)
	if err != nil {
		return nil, err
	}

	m := &MuxSession{
		conn:    conn,
		cfg:     c,
		done:    make(chan struct{}),
		streams: make(map[uint32]*MuxStream),
	}
	m.cond = sync.NewCond(&m.mu)

	if c.Side == MuxSideClient {
		m.nextID = 1
	} else {
		m.nextID = 2
	}

	go m.readLoop()
	go m.writeLoop()

	return m, nil
}

func normalizeMuxConfig(cfg *MuxConfig) (MuxConfig, error) {
	c := DefaultMuxConfig()
	if cfg != nil {
		c.Side = cfg.Side
		if cfg.MaxFrameSize > 0 {
			c.MaxFrameSize = cfg.MaxFrameSize
		}
		if cfg.SendWindow > 0 {
			c.SendWindow = cfg.SendWindow
		}
		if cfg.RecvWindow > 0 {
			c.RecvWindow = cfg.RecvWindow
		}
	}

	if c.Side != MuxSideClient && c.Side != MuxSideServer {
		return MuxConfig{}, errMuxInvalidConfig
	}
	if c.MaxFrameSize <= 0 || c.MaxFrameSize > muxMaxFrameSizeLimit {
		return MuxConfig{}, errMuxInvalidConfig
	}
	if c.SendWindow <= 0 || c.RecvWindow <= 0 {
		return MuxConfig{}, errMuxInvalidConfig
	}
	return c, nil
}

// Close shuts down the mux session promptly. It does not wait for the
// background reader/writer goroutines; the underlying connection is closed in a
// goroutine so Close is not held up by an externally blocked Write.
func (m *MuxSession) Close() error {
	if !m.shutdown(true) {
		return io.ErrClosedPipe
	}
	return nil
}

func (m *MuxSession) shutdown(closeConn bool) bool {
	var did bool
	var forcedClosedStreams int

	m.closeOne.Do(func() {
		did = true

		m.mu.Lock()
		m.closed = true
		close(m.done)

		forcedClosedStreams = len(m.streams)
		for _, s := range m.streams {
			s.localClosed = true
			s.remoteClosed = true
			s.removed = true
			s.sendQ = nil
		}
		m.streams = make(map[uint32]*MuxStream)
		m.acceptQ = nil
		m.controlQ = nil
		m.cond.Broadcast()
		m.mu.Unlock()

		if forcedClosedStreams > 0 {
			atomic.AddUint64(&DefaultSnmp.MuxStreamsClosed, uint64(forcedClosedStreams))
		}

		if closeConn {
			go func() { _ = m.conn.Close() }()
		}
	})

	return did
}

// NumStreams returns the number of streams currently tracked by the session.
func (m *MuxSession) NumStreams() int {
	m.mu.Lock()
	defer m.mu.Unlock()
	return len(m.streams)
}

// OpenStream opens a locally initiated stream. Client streams use odd stream
// IDs and server streams use even stream IDs.
func (m *MuxSession) OpenStream(priority uint8) (*MuxStream, error) {
	priority = normalizeMuxPriority(priority)

	m.mu.Lock()
	defer m.mu.Unlock()

	if m.closed {
		return nil, io.ErrClosedPipe
	}
	if m.nextID == 0 {
		return nil, errMuxIDExhausted
	}

	id := m.nextID
	if ^uint32(0)-m.nextID < 2 {
		m.nextID = 0
	} else {
		m.nextID += 2
	}

	s := m.newStreamLocked(id, priority)
	m.streams[id] = s
	m.controlQ = append(m.controlQ, muxFrame{typ: muxFrameOpen, streamID: id, arg: uint32(priority)})
	atomic.AddUint64(&DefaultSnmp.MuxStreamsOpened, 1)
	m.cond.Broadcast()

	return s, nil
}

// AcceptStream waits for and returns the next remotely opened stream.
func (m *MuxSession) AcceptStream() (*MuxStream, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	for {
		if len(m.acceptQ) > 0 {
			s := m.acceptQ[0]
			m.acceptQ[0] = nil
			m.acceptQ = m.acceptQ[1:]
			return s, nil
		}
		if m.closed {
			return nil, io.ErrClosedPipe
		}
		m.cond.Wait()
	}
}

func (m *MuxSession) newStreamLocked(id uint32, priority uint8) *MuxStream {
	return &MuxStream{
		sess:       m,
		id:         id,
		priority:   priority,
		sendCredit: int64(m.cfg.SendWindow),
	}
}

func normalizeMuxPriority(priority uint8) uint8 {
	switch priority {
	case MuxPriorityHigh, MuxPriorityNormal, MuxPriorityLow:
		return priority
	default:
		return MuxPriorityNormal
	}
}

func (m *MuxSession) remoteStreamIDOK(id uint32) bool {
	if id == 0 {
		return false
	}
	if m.cfg.Side == MuxSideClient {
		return id%2 == 0
	}
	return id%2 == 1
}

func (m *MuxSession) readLoop() {
	for {
		f, err := readMuxFrame(m.conn, m.cfg.MaxFrameSize)
		if err != nil {
			m.shutdown(true)
			return
		}

		atomic.AddUint64(&DefaultSnmp.MuxFramesReceived, 1)
		if f.typ == muxFrameData {
			atomic.AddUint64(&DefaultSnmp.MuxBytesReceived, uint64(len(f.payload)))
		}

		if err := m.handleFrame(f); err != nil {
			m.shutdown(true)
			return
		}
	}
}

func (m *MuxSession) handleFrame(f muxFrame) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.closed {
		return nil
	}

	switch f.typ {
	case muxFrameOpen:
		return m.handleOpenFrameLocked(f)
	case muxFrameData:
		return m.handleDataFrameLocked(f)
	case muxFrameWindowUpdate:
		m.handleWindowUpdateFrameLocked(f)
	case muxFrameClose:
		m.handleCloseFrameLocked(f)
	default:
		return errMuxProtocol
	}
	return nil
}

func (m *MuxSession) handleOpenFrameLocked(f muxFrame) error {
	if !m.remoteStreamIDOK(f.streamID) {
		return errMuxProtocol
	}
	if _, ok := m.streams[f.streamID]; ok {
		return errMuxProtocol
	}

	priority := normalizeMuxPriority(uint8(f.arg))
	s := m.newStreamLocked(f.streamID, priority)
	m.streams[f.streamID] = s
	m.acceptQ = append(m.acceptQ, s)
	atomic.AddUint64(&DefaultSnmp.MuxStreamsOpened, 1)
	m.cond.Broadcast()
	return nil
}

func (m *MuxSession) handleDataFrameLocked(f muxFrame) error {
	s := m.streams[f.streamID]
	if s == nil || s.removed {
		return nil
	}
	if s.remoteClosed {
		return errMuxProtocol
	}
	if len(f.payload) == 0 {
		return nil
	}
	if s.recvBuf.Len()+len(f.payload) > m.cfg.RecvWindow {
		return errMuxProtocol
	}
	_, _ = s.recvBuf.Write(f.payload)
	m.cond.Broadcast()
	return nil
}

func (m *MuxSession) handleWindowUpdateFrameLocked(f muxFrame) {
	if f.arg == 0 {
		return
	}
	s := m.streams[f.streamID]
	if s == nil || s.removed {
		return
	}
	s.sendCredit += int64(f.arg)
	if maxCredit := int64(m.cfg.SendWindow); s.sendCredit > maxCredit {
		s.sendCredit = maxCredit
	}
	m.cond.Broadcast()
}

func (m *MuxSession) handleCloseFrameLocked(f muxFrame) {
	s := m.streams[f.streamID]
	if s == nil || s.removed {
		return
	}
	s.remoteClosed = true
	m.cond.Broadcast()
	m.tryRemoveStreamLocked(s)
}

func (m *MuxSession) writeLoop() {
	for {
		m.mu.Lock()
		var f muxFrame
		var ok bool
		for !m.closed {
			f, ok = m.nextFrameLocked()
			if ok {
				break
			}
			m.cond.Wait()
		}
		if m.closed {
			m.mu.Unlock()
			return
		}
		m.mu.Unlock()

		if err := writeMuxFrame(m.conn, f); err != nil {
			m.shutdown(true)
			return
		}

		atomic.AddUint64(&DefaultSnmp.MuxFramesSent, 1)
		if f.typ == muxFrameData {
			atomic.AddUint64(&DefaultSnmp.MuxBytesSent, uint64(len(f.payload)))
		} else if f.typ == muxFrameClose {
			m.afterCloseFrameSent(f.streamID)
		}
	}
}

func (m *MuxSession) nextFrameLocked() (muxFrame, bool) {
	if len(m.controlQ) > 0 {
		f := m.controlQ[0]
		m.controlQ[0] = muxFrame{}
		m.controlQ = m.controlQ[1:]
		return f, true
	}

	// CLOSE is a control frame. If it is the next frame for any stream, send it
	// before any DATA frame from any stream, while still preserving that stream's
	// own DATA-before-CLOSE ordering.
	for _, s := range m.streams {
		if len(s.sendQ) > 0 && s.sendQ[0].typ == muxFrameClose {
			return popMuxStreamFrame(s), true
		}
	}

	for _, priority := range [...]uint8{MuxPriorityHigh, MuxPriorityNormal, MuxPriorityLow} {
		for _, s := range m.streams {
			if s.priority != priority || len(s.sendQ) == 0 {
				continue
			}
			if s.sendQ[0].typ == muxFrameData {
				return popMuxStreamFrame(s), true
			}
		}
	}

	return muxFrame{}, false
}

func popMuxStreamFrame(s *MuxStream) muxFrame {
	f := s.sendQ[0]
	s.sendQ[0] = muxFrame{}
	s.sendQ = s.sendQ[1:]
	return f
}

func (m *MuxSession) afterCloseFrameSent(streamID uint32) {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.closed {
		return
	}
	if s := m.streams[streamID]; s != nil {
		m.tryRemoveStreamLocked(s)
	}
}

func (m *MuxSession) tryRemoveStreamLocked(s *MuxStream) {
	if s == nil || s.removed || m.closed {
		return
	}
	if s.localClosed && s.remoteClosed && s.recvBuf.Len() == 0 && len(s.sendQ) == 0 {
		s.removed = true
		delete(m.streams, s.id)
		atomic.AddUint64(&DefaultSnmp.MuxStreamsClosed, 1)
		m.cond.Broadcast()
	}
}

// ID returns the stream ID. Client-initiated streams are odd, server-initiated
// streams are even, and IDs match on both peers.
func (s *MuxStream) ID() uint32 { return s.id }

// Read reads ordered bytes from the stream. After the remote peer half-closes
// and buffered data is drained, Read returns io.EOF. If the session is closed,
// blocked readers are unblocked with io.ErrClosedPipe.
func (s *MuxStream) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}

	m := s.sess
	m.mu.Lock()
	defer m.mu.Unlock()

	for {
		if m.closed {
			return 0, io.ErrClosedPipe
		}
		if s.recvBuf.Len() > 0 {
			n, _ := s.recvBuf.Read(p)
			if n > 0 && !s.remoteClosed && !s.removed {
				m.enqueueWindowUpdateLocked(s.id, n)
			}
			if s.recvBuf.Len() == 0 {
				m.tryRemoveStreamLocked(s)
			}
			return n, nil
		}
		if s.remoteClosed {
			m.tryRemoveStreamLocked(s)
			return 0, io.EOF
		}
		if s.removed {
			return 0, io.ErrClosedPipe
		}

		deadline := s.readDeadline
		if !deadline.IsZero() {
			d := time.Until(deadline)
			if d <= 0 {
				return 0, errTimeout
			}
			timer := time.AfterFunc(d, func() {
				m.mu.Lock()
				m.cond.Broadcast()
				m.mu.Unlock()
			})
			m.cond.Wait()
			timer.Stop()
		} else {
			m.cond.Wait()
		}
	}
}

// Write writes all bytes to the stream or returns an error. It blocks when the
// stream's byte-level send window has no credit and resumes when WINDOW_UPDATE
// frames arrive. It never returns a short write unless it also returns an error.
func (s *MuxStream) Write(p []byte) (int, error) {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()

	m := s.sess
	written := 0

	for len(p) > written {
		m.mu.Lock()
		for {
			if m.closed || s.removed || s.localClosed || s.remoteClosed {
				m.mu.Unlock()
				if written > 0 {
					return written, io.ErrClosedPipe
				}
				return 0, io.ErrClosedPipe
			}
			if s.sendCredit > 0 {
				break
			}
			m.cond.Wait()
		}

		n := len(p) - written
		if n > m.cfg.MaxFrameSize {
			n = m.cfg.MaxFrameSize
		}
		if int64(n) > s.sendCredit {
			n = int(s.sendCredit)
		}

		payload := make([]byte, n)
		copy(payload, p[written:written+n])
		s.sendCredit -= int64(n)
		s.sendQ = append(s.sendQ, muxFrame{typ: muxFrameData, streamID: s.id, payload: payload})
		written += n
		m.cond.Signal()
		m.mu.Unlock()
	}

	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed || s.removed || s.localClosed || s.remoteClosed {
		return 0, io.ErrClosedPipe
	}
	return 0, nil
}

// Close half-closes the local write side of the stream. Already-buffered inbound
// data remains readable until drained.
func (s *MuxStream) Close() error {
	m := s.sess
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.closed || s.removed || s.localClosed {
		return io.ErrClosedPipe
	}
	s.localClosed = true
	s.sendQ = append(s.sendQ, muxFrame{typ: muxFrameClose, streamID: s.id})
	m.cond.Broadcast()
	m.tryRemoveStreamLocked(s)
	return nil
}

// SetReadDeadline sets the stream read deadline. Expiry causes Read to return
// an error satisfying net.Error with Timeout() true.
func (s *MuxStream) SetReadDeadline(t time.Time) error {
	m := s.sess
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.closed || s.removed {
		return io.ErrClosedPipe
	}
	s.readDeadline = t
	m.cond.Broadcast()
	return nil
}

func (m *MuxSession) enqueueWindowUpdateLocked(streamID uint32, n int) {
	for n > 0 {
		inc := n
		if inc > int(^uint32(0)) {
			inc = int(^uint32(0))
		}
		m.controlQ = append(m.controlQ, muxFrame{typ: muxFrameWindowUpdate, streamID: streamID, arg: uint32(inc)})
		n -= inc
	}
	m.cond.Signal()
}

func readMuxFrame(r io.Reader, maxFrameSize int) (muxFrame, error) {
	var header [muxFrameHeaderSize]byte
	if _, err := io.ReadFull(r, header[:]); err != nil {
		return muxFrame{}, err
	}

	f := muxFrame{
		typ:      header[0],
		streamID: binary.BigEndian.Uint32(header[1:5]),
		arg:      binary.BigEndian.Uint32(header[5:9]),
	}

	switch f.typ {
	case muxFrameOpen, muxFrameWindowUpdate, muxFrameClose:
		if f.streamID == 0 {
			return muxFrame{}, errMuxProtocol
		}
		return f, nil
	case muxFrameData:
		if f.streamID == 0 {
			return muxFrame{}, errMuxProtocol
		}
		if f.arg > uint32(maxFrameSize) {
			return muxFrame{}, errMuxFrameTooLarge
		}
		if f.arg > 0 {
			f.payload = make([]byte, int(f.arg))
			if _, err := io.ReadFull(r, f.payload); err != nil {
				return muxFrame{}, err
			}
		}
		return f, nil
	default:
		return muxFrame{}, errMuxProtocol
	}
}

func writeMuxFrame(w io.Writer, f muxFrame) error {
	payloadLen := 0
	arg := f.arg
	if f.typ == muxFrameData {
		payloadLen = len(f.payload)
		arg = uint32(payloadLen)
	}

	buf := make([]byte, muxFrameHeaderSize+payloadLen)
	buf[0] = f.typ
	binary.BigEndian.PutUint32(buf[1:5], f.streamID)
	binary.BigEndian.PutUint32(buf[5:9], arg)
	if payloadLen > 0 {
		copy(buf[muxFrameHeaderSize:], f.payload)
	}
	return writeFull(w, buf)
}

func writeFull(w io.Writer, p []byte) error {
	for len(p) > 0 {
		n, err := w.Write(p)
		if n > 0 {
			p = p[n:]
		}
		if err != nil {
			return err
		}
		if n == 0 {
			return io.ErrUnexpectedEOF
		}
	}
	return nil
}
