func TestMuxFlowControlBlockedStreamDoesNotStallOtherStreams(t *testing.T) {
	cfg := DefaultMuxConfig()
	cfg.MaxFrameSize = 8
	cfg.SendWindow = 16
	cfg.RecvWindow = 16
	client, server, cleanup := newMuxPipeForTest(t, cfg)
	defer cleanup()

	low, err := client.OpenStream(MuxPriorityLow)
	if err != nil {
		t.Fatalf("open low stream: %v", err)
	}
	high, err := client.OpenStream(MuxPriorityHigh)
	if err != nil {
		t.Fatalf("open high stream: %v", err)
	}
	serverLow := acceptMuxStreamWithTimeout(t, server)
	serverHigh := acceptMuxStreamWithTimeout(t, server)
	if serverLow.ID() != low.ID() || serverHigh.ID() != high.ID() {
		t.Fatalf("accepted streams out of order: got %d/%d want %d/%d", serverLow.ID(), serverHigh.ID(), low.ID(), high.ID())
	}

	lowPayload := bytes.Repeat([]byte("l"), 32)
	lowDone := make(chan error, 1)
	go func() {
		n, err := low.Write(lowPayload)
		if err != nil {
			lowDone <- err
			return
		}
		if n != len(lowPayload) {
			lowDone <- errors.New("short low write without error")
			return
		}
		lowDone <- nil
	}()

	select {
	case err := <-lowDone:
		t.Fatalf("low-priority write completed before window update: %v", err)
	case <-time.After(50 * time.Millisecond):
	}

	if n, err := high.Write([]byte("hi")); err != nil || n != 2 {
		t.Fatalf("high-priority Write while low blocked = %d, %v", n, err)
	}
	if err := serverHigh.SetReadDeadline(time.Now().Add(time.Second)); err != nil {
		t.Fatalf("serverHigh SetReadDeadline: %v", err)
	}
	highBuf := make([]byte, 2)
	if _, err := io.ReadFull(serverHigh, highBuf); err != nil {
		t.Fatalf("serverHigh ReadFull: %v", err)
	}
	if string(highBuf) != "hi" {
		t.Fatalf("serverHigh read %q, want hi", highBuf)
	}

	if err := serverLow.SetReadDeadline(time.Now().Add(time.Second)); err != nil {
		t.Fatalf("serverLow SetReadDeadline: %v", err)
	}
	firstWindow := make([]byte, 16)
	if _, err := io.ReadFull(serverLow, firstWindow); err != nil {
		t.Fatalf("serverLow first ReadFull: %v", err)
	}

	select {
	case err := <-lowDone:
		if err != nil {
			t.Fatalf("low write after window update: %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("low write did not resume after window update")
	}

	rest := make([]byte, 16)
	if _, err := io.ReadFull(serverLow, rest); err != nil {
		t.Fatalf("serverLow second ReadFull: %v", err)
	}
}

