func TestMuxSchedulerPriorityAndControl(t *testing.T) {
	cfg := DefaultMuxConfig()
	m := &MuxSession{cfg: cfg, streams: make(map[uint32]*MuxStream)}
	low := &MuxStream{id: 1, priority: MuxPriorityLow}
	high := &MuxStream{id: 3, priority: MuxPriorityHigh}
	m.streams[low.id] = low
	m.streams[high.id] = high
	m.controlQ = append(m.controlQ, muxFrame{typ: muxFrameWindowUpdate, streamID: low.id, arg: 1})
	low.sendQ = append(low.sendQ, muxFrame{typ: muxFrameData, streamID: low.id, payload: []byte("low")})
	high.sendQ = append(high.sendQ, muxFrame{typ: muxFrameData, streamID: high.id, payload: []byte("high")})

	f, ok := m.nextFrameLocked()
	if !ok || f.typ != muxFrameWindowUpdate {
		t.Fatalf("first scheduled frame = %+v, %v; want WINDOW_UPDATE control", f, ok)
	}
	f, ok = m.nextFrameLocked()
	if !ok || f.streamID != high.id || f.typ != muxFrameData {
		t.Fatalf("second scheduled frame = %+v, %v; want high DATA", f, ok)
	}

	closer := &MuxStream{id: 5, priority: MuxPriorityLow}
	closer.sendQ = append(closer.sendQ, muxFrame{typ: muxFrameClose, streamID: closer.id})
	m.streams[closer.id] = closer
	f, ok = m.nextFrameLocked()
	if !ok || f.typ != muxFrameClose || f.streamID != closer.id {
		t.Fatalf("third scheduled frame = %+v, %v; want CLOSE before DATA", f, ok)
	}
}

func TestMuxSnmpCounters(t *testing.T) {
	DefaultSnmp.Reset()

	cfg := DefaultMuxConfig()
	cfg.MaxFrameSize = 8
	client, server, cleanup := newMuxPipeForTest(t, cfg)
	defer cleanup()

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatalf("OpenStream: %v", err)
	}
	remote := acceptMuxStreamWithTimeout(t, server)

	payload := []byte("abcdef")
	if n, err := stream.Write(payload); err != nil || n != len(payload) {
		t.Fatalf("Write = %d, %v", n, err)
	}
	buf := make([]byte, len(payload))
	if _, err := io.ReadFull(remote, buf); err != nil {
		t.Fatalf("ReadFull: %v", err)
	}
	if !bytes.Equal(buf, payload) {
		t.Fatalf("read %q, want %q", buf, payload)
	}

	waitMuxCondition(t, time.Second, func() bool {
		s := DefaultSnmp.Copy()
		return s.MuxStreamsOpened >= 2 &&
			s.MuxFramesSent > 0 && s.MuxFramesReceived > 0 &&
			s.MuxBytesSent >= uint64(len(payload)) &&
			s.MuxBytesReceived >= uint64(len(payload))
	}, "mux SNMP counters did not advance")

	if len(DefaultSnmp.Header()) != len(DefaultSnmp.ToSlice()) {
		t.Fatalf("SNMP Header/ToSlice length mismatch: %d/%d", len(DefaultSnmp.Header()), len(DefaultSnmp.ToSlice()))
	}

	if err := stream.Close(); err != nil {
		t.Fatalf("stream Close: %v", err)
	}
	_ = readAllMuxWithTimeout(t, remote)
	if err := remote.Close(); err != nil {
		t.Fatalf("remote Close: %v", err)
	}
	_ = readAllMuxWithTimeout(t, stream)

	waitMuxCondition(t, time.Second, func() bool {
		return DefaultSnmp.Copy().MuxStreamsClosed >= 2
	}, "MuxStreamsClosed did not advance")

	DefaultSnmp.Reset()
	if s := DefaultSnmp.Copy(); s.MuxStreamsOpened != 0 || s.MuxStreamsClosed != 0 || s.MuxFramesSent != 0 ||
		s.MuxFramesReceived != 0 || s.MuxBytesSent != 0 || s.MuxBytesReceived != 0 {
		t.Fatalf("mux SNMP counters did not reset: %+v", s)
	}
}

