	writeStarted chan struct{}
	closeStarted chan struct{}
	writeOnce    sync.Once
	closeOnce    sync.Once
}

func newStuckMuxConn() *stuckMuxConn {
	return &stuckMuxConn{
		writeStarted: make(chan struct{}),
		closeStarted: make(chan struct{}),
	}
}

func (c *stuckMuxConn) Read([]byte) (int, error) {
	select {}
}

func (c *stuckMuxConn) Write([]byte) (int, error) {
	c.writeOnce.Do(func() { close(c.writeStarted) })
	select {}
}

func (c *stuckMuxConn) Close() error {
	c.closeOnce.Do(func() { close(c.closeStarted) })
	select {}
}

