	}

	select {
	case <-conn.writeStarted:
	case <-time.After(time.Second):
		t.Fatal("writer did not enter blocked underlying Write")
	}

	done := make(chan error, 1)
	start := time.Now()
	go func() { done <- sess.Close() }()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("Close: %v", err)
		}
		if elapsed := time.Since(start); elapsed > 100*time.Millisecond {
			t.Fatalf("Close took %v with blocked underlying Write", elapsed)
		}
	case <-time.After(200 * time.Millisecond):
		t.Fatal("Close blocked while underlying Write was blocked")
	}

	select {
	case <-conn.closeStarted:
	case <-time.After(time.Second):
		t.Fatal("underlying Close was not signaled")
	}
}
