// https://developer.mozilla.org/en-US/docs/Web/API/Response/body
const nullBodyResponses = new Set([101, 204, 205, 304]);

interface ResolvedCircuitBreakerOptions
  extends Required<CircuitBreakerOptions> {}

type CircuitBreakerStateName = "closed" | "open" | "half-open";

type CircuitBreakerOutcome = "success" | "failure" | "neutral";

interface CircuitBreakerState {
  state: CircuitBreakerStateName;
  consecutiveFailures: number;
  openedAt: number;
  halfOpenInFlight: number;
}

type CircuitBreakerStateMap = Map<string, CircuitBreakerState>;

interface CircuitBreakerOperation {
  state: CircuitBreakerState;
  options: ResolvedCircuitBreakerOptions;
  probe: boolean;
  outcome?: CircuitBreakerOutcome;
}

const circuitBreakerOperationKey: unique symbol = Symbol(
  "ofetch.circuitBreakerOperation"
);

interface InternalFetchOptions<R extends ResponseType = ResponseType>
  extends FetchOptions<R> {
  [circuitBreakerOperationKey]?: CircuitBreakerOperation;
}

interface InternalCreateFetchOptions extends CreateFetchOptions {
  _circuitBreakerState?: CircuitBreakerStateMap;
}

const defaultCircuitBreakerOptions: ResolvedCircuitBreakerOptions = {
  threshold: 5,
  cooldown: 30_000,
  halfOpenMaxRequests: 1,
  failureStatusCodes: [...retryStatusCodes],
};

function resolveCircuitBreakerOptions(
  input: FetchOptions["circuitBreaker"]
): ResolvedCircuitBreakerOptions | undefined {
  if (!input) {
    return undefined;
  }

  const options = input === true ? undefined : input;

  return {
    threshold: options?.threshold ?? defaultCircuitBreakerOptions.threshold,
    cooldown: options?.cooldown ?? defaultCircuitBreakerOptions.cooldown,
    halfOpenMaxRequests:
      options?.halfOpenMaxRequests ??
      defaultCircuitBreakerOptions.halfOpenMaxRequests,
    failureStatusCodes: [
      ...(options?.failureStatusCodes ??
        defaultCircuitBreakerOptions.failureStatusCodes),
    ],
  };
}

function getCircuitBreakerOperation(
  options: FetchOptions
): CircuitBreakerOperation | undefined {
  return (options as InternalFetchOptions)[circuitBreakerOperationKey];
}

function setCircuitBreakerOperation(
  options: FetchOptions,
  operation: CircuitBreakerOperation
): void {
  (options as InternalFetchOptions)[circuitBreakerOperationKey] = operation;
}

function resolveRequestOrigin(request: FetchRequest): string | undefined {
  try {
    if (typeof request === "string") {
      return new URL(request).origin;
    }

    if (request instanceof URL) {
      return request.origin;
    }

    const url = (request as Request | undefined)?.url;
    if (url) {
      return new URL(url).origin;
    }
  } catch {
    // Ignore malformed or still-relative requests and let fetch handle them.
  }
}

function getCircuitBreakerState(
  states: CircuitBreakerStateMap,
  origin: string
): CircuitBreakerState {
  let state = states.get(origin);
  if (!state) {
    state = {
      state: "closed",
      consecutiveFailures: 0,
      openedAt: 0,
      halfOpenInFlight: 0,
    };
    states.set(origin, state);
  }
  return state;
}

function openCircuitBreaker(state: CircuitBreakerState): void {
  state.state = "open";
  state.openedAt = Date.now();
  state.halfOpenInFlight = 0;
}

function closeCircuitBreaker(state: CircuitBreakerState): void {
  state.state = "closed";
  state.consecutiveFailures = 0;
  state.halfOpenInFlight = 0;
}

function acquireCircuitBreakerOperation(
  states: CircuitBreakerStateMap,
  origin: string,
  options: ResolvedCircuitBreakerOptions
): CircuitBreakerOperation | undefined {
  const state = getCircuitBreakerState(states, origin);

  if (state.state === "open") {
    const now = Date.now();
    if (now - state.openedAt >= options.cooldown) {
      state.state = "half-open";
      state.halfOpenInFlight = 0;
    } else {
      return undefined;
    }
  }

  if (state.state === "half-open") {
    if (state.halfOpenInFlight >= options.halfOpenMaxRequests) {
      return undefined;
    }
    state.halfOpenInFlight++;
    return { state, options, probe: true };
  }

  return { state, options, probe: false };
