function isCircuitBreakerFailureStatus(
  response: Response,
  options: ResolvedCircuitBreakerOptions
): boolean {
  return options.failureStatusCodes.includes(response.status);
}

function getCircuitBreakerErrorOutcome(
  context: FetchContext,
  options: ResolvedCircuitBreakerOptions
): CircuitBreakerOutcome {
  if (!context.response) {
    return "failure";
  }
  return isCircuitBreakerFailureStatus(context.response, options)
    ? "failure"
    : "neutral";
}

function setCircuitBreakerResponseOutcome(
  operation: CircuitBreakerOperation | undefined,
  response: Response
): void {
  if (!operation) {
    return;
  }
  operation.outcome = isCircuitBreakerFailureStatus(response, operation.options)
    ? "failure"
    : "success";
}

function finalizeCircuitBreakerOperation(
  operation: CircuitBreakerOperation,
  outcome: CircuitBreakerOutcome
): void {
  const { state } = operation;

  if (operation.probe) {
    state.halfOpenInFlight = Math.max(0, state.halfOpenInFlight - 1);
  }

  if (outcome === "neutral") {
    return;
  }

  if (operation.probe) {
    if (outcome === "success") {
      closeCircuitBreaker(state);
    } else {
      openCircuitBreaker(state);
    }
    return;
  }

  if (outcome === "success") {
    closeCircuitBreaker(state);
    return;
  }

  state.consecutiveFailures++;
  if (state.consecutiveFailures >= operation.options.threshold) {
    openCircuitBreaker(state);
  }
