    ).rejects.toThrow();
    await expect(
      api("https://disabled-circuit.test/two", {
        ...textOptions,
        circuitBreaker: false,
      })
    ).rejects.toThrow();
    await expect(
      api("https://disabled-circuit.test/three", textOptions)
    ).rejects.toThrow();

    expect(fetch).toHaveBeenCalledTimes(3);
