package termenv

import ansiutil "github.com/muesli/termenv/ansi"

// TruncateOptions configures ANSI-aware truncation.
type TruncateOptions = ansiutil.TruncateOptions

// TruncateANSI truncates s to width printable cells without splitting ANSI CSI
// or OSC sequences.
func TruncateANSI(s string, width int, opts TruncateOptions) string {
	return ansiutil.TruncateANSI(s, width, opts)
}

// StripANSI removes ANSI CSI and OSC sequences from s.
func StripANSI(s string) string {
	return ansiutil.StripANSI(s)
}

// ANSIWidth returns the printable cell width of s with ANSI sequences ignored.
func ANSIWidth(s string) int {
	return ansiutil.ANSIWidth(s)
}

// HasANSI reports whether s contains ANSI CSI or OSC sequences.
func HasANSI(s string) bool {
	return ansiutil.HasANSI(s)
}

// Truncate truncates s to width printable cells using the Output's profile and
// preserve-resets default.
func (o Output) Truncate(s string, width int, opts TruncateOptions) string {
	if o.Profile == Ascii {
		return ansiutil.TruncateANSI(
			ansiutil.StripANSI(s),
			width,
			ansiutil.TruncateOptions{Tail: ansiutil.StripANSI(opts.Tail)},
		)
	}

	if o.preserveResets || opts.PreserveResets {
		opts.PreserveResets = true
	}
	return ansiutil.TruncateANSI(s, width, opts)
}
EOF"}

