cat <<'EOF' > templatehelper.go
package termenv

import (
	"fmt"
	"strconv"
	"text/template"
)

// TemplateFuncs returns template helpers for the given output.
func (o Output) TemplateFuncs() template.FuncMap {
	return templateFuncs(o.Profile, o.preserveResets)
}

// TemplateFuncs contains a few useful template helpers.
//
//nolint:mnd
func TemplateFuncs(p Profile) template.FuncMap {
	return templateFuncs(p, false)
}

func templateFuncs(p Profile, preserveResets bool) template.FuncMap {
	o := Output{Profile: p, preserveResets: preserveResets}

	return template.FuncMap{
		"Color": func(values ...interface{}) string {
			s := o.String(fmt.Sprint(values[len(values)-1]))
			switch len(values) {
			case 2:
				s = s.Foreground(p.Color(fmt.Sprint(values[0])))
			case 3:
				s = s.
					Foreground(p.Color(fmt.Sprint(values[0]))).
					Background(p.Color(fmt.Sprint(values[1])))
			}

			return s.String()
		},
		"Foreground": func(values ...interface{}) string {
			s := o.String(fmt.Sprint(values[len(values)-1]))
			if len(values) == 2 {
				s = s.Foreground(p.Color(fmt.Sprint(values[0])))
			}

			return s.String()
		},
		"Background": func(values ...interface{}) string {
			s := o.String(fmt.Sprint(values[len(values)-1]))
			if len(values) == 2 {
				s = s.Background(p.Color(fmt.Sprint(values[0])))
			}

			return s.String()
		},
		"Bold":      styleFunc(o, Style.Bold),
		"Faint":     styleFunc(o, Style.Faint),
		"Italic":    styleFunc(o, Style.Italic),
		"Underline": styleFunc(o, Style.Underline),
		"Overline":  styleFunc(o, Style.Overline),
		"Blink":     styleFunc(o, Style.Blink),
		"Reverse":   styleFunc(o, Style.Reverse),
		"CrossOut":  styleFunc(o, Style.CrossOut),
		"Truncate": func(values ...interface{}) string {
			if len(values) != 3 {
				return ""
			}
			return o.Truncate(fmt.Sprint(values[2]), templateInt(values[0]), TruncateOptions{Tail: fmt.Sprint(values[1])})
		},
		"truncate": func(values ...interface{}) string {
			if len(values) != 2 {
				return ""
			}
			return o.Truncate(fmt.Sprint(values[1]), templateInt(values[0]), TruncateOptions{})
		},
	}
}

func styleFunc(o Output, f func(Style) Style) func(...interface{}) string {
	return func(values ...interface{}) string {
		s := o.String(fmt.Sprint(values[0]))
		return f(s).String()
	}
}

func templateInt(v interface{}) int {
	switch n := v.(type) {
	case int:
		return n
	case int8:
		return int(n)
	case int16:
		return int(n)
	case int32:
		return int(n)
	case int64:
		return int(n)
	case uint:
		return int(n)
	case uint8:
		return int(n)
	case uint16:
		return int(n)
	case uint32:
		return int(n)
	case uint64:
		return int(n)
	case string:
		i, _ := strconv.Atoi(n)
		return i
	default:
		i, _ := strconv.Atoi(fmt.Sprint(v))
		return i
	}
}
