package ansi

import "testing"

func TestTokenize(t *testing.T) {
	input := "a\x1b[31mb\x1b[mc\x1b]8;;https://example.com\x1b\\d\x1b]8;;\x1b\\"
	tokens := Tokenize(input)
	wantTypes := []TokenType{
