const (
	esc = '\x1b'
	bel = '\a'

	csiPrefix           = "\x1b["
	oscPrefix           = "\x1b]"
	st                  = "\x1b\\"
	sgrReset            = "\x1b[0m"
	hyperlinkClose      = "\x1b]8;;\x1b\\"
	sgrFinal       byte = 'm'
