+// Package ansi provides helpers for tokenizing, measuring, stripping, and
+// truncating ANSI-escaped strings.
+package ansi
+
+import (
+	"strconv"
+	"strings"
+	"unicode/utf8"
+
+	"github.com/rivo/uniseg"
+)
+
+const (
+	esc = '\x1b'
+	bel = '\a'
+
+	csiPrefix           = "\x1b["
+	oscPrefix           = "\x1b]"
+	sgrReset            = "\x1b[0m"
+	hyperlinkClose      = "\x1b]8;;\x1b\\"
+	sgrFinal       byte = 'm'
+)
+
+// TokenType identifies the type of an ANSI token.
+type TokenType int
+
+const (
+	// TokenText is printable text.
+	TokenText TokenType = iota
+	// TokenSGR is an SGR escape sequence, or another zero-width CSI/OSC
+	// sequence that does not have a more specific token type.
+	TokenSGR
+	// TokenReset is an SGR sequence that resets terminal rendition.
+	TokenReset
+	// TokenHyperlinkOpen is an OSC 8 hyperlink open sequence.
+	TokenHyperlinkOpen
+	// TokenHyperlinkClose is an OSC 8 hyperlink close sequence.
+	TokenHyperlinkClose
+)
+
+// Token is one ANSI-aware token. Raw contains the original bytes for the token.
+// Text contains the visible text for TokenText tokens and is empty for ANSI
+// control tokens.
+type Token struct {
+	Type TokenType
+	Raw  string
+	Text string
+}
+
+// TruncateOptions configures TruncateANSI.
+type TruncateOptions struct {
+	Tail           string
+	PreserveResets bool
+}
+
+// Tokenize splits s into text and ANSI control tokens. CSI and OSC sequences are
+// emitted as single zero-width tokens so callers never have to split them.
+func Tokenize(s string) []Token {
+	var (
+		tokens []Token
+		text   strings.Builder
+	)
+
+	flushText := func() {
+		if text.Len() == 0 {
+			return
+		}
+		raw := text.String()
+		tokens = append(tokens, Token{Type: TokenText, Raw: raw, Text: raw})
+		text.Reset()
+	}
+
+	for i := 0; i < len(s); {
+		if s[i] == esc && i+1 < len(s) {
+			switch s[i+1] {
+			case '[':
+				if raw, ok, next := readCSI(s, i); ok {
+					flushText()
+					tokens = append(tokens, csiToken(raw))
+					i = next
+					continue
+				}
+			case ']':
+				if raw, content, ok, next := readOSC(s, i); ok {
+					flushText()
+					tokens = append(tokens, oscToken(raw, content))
+					i = next
+					continue
+				}
+			}
+		}
+
+		r, size := utf8.DecodeRuneInString(s[i:])
+		if r == utf8.RuneError && size == 0 {
+			break
+		}
+		if size == 0 {
+			size = 1
+		}
+		text.WriteString(s[i : i+size])
+		i += size
+	}
+	flushText()
+
+	return tokens
+}
+
+// TruncateANSI truncates s to width printable cells without splitting ANSI CSI
+// or OSC sequences. ANSI sequences have zero width. If truncation occurs, Tail
+// is appended and counts toward width. The tail is written at the truncation
+// point, so it inherits the active style and hyperlink. Open SGR styles are
+// reset and open OSC 8 hyperlinks are closed in the returned string.
+func TruncateANSI(s string, width int, opts TruncateOptions) string {
+	if width <= 0 {
+		return ""
+	}
+
+	tokens := Tokenize(s)
+	if tokensWidth(tokens) <= width {
+		return renderAll(tokens, opts.PreserveResets)
+	}
+
+	tail := opts.Tail
+	tailWidth := ANSIWidth(tail)
+	if tailWidth > width {
+		tail = truncateOnly(tail, width)
+		tailWidth = ANSIWidth(tail)
+	}
+
+	limit := width - tailWidth
+	if limit < 0 {
+		limit = 0
+	}
+
+	r := renderPrefix(tokens, limit, opts.PreserveResets, tail != "")
+	if tail != "" {
+		r.writeTokens(Tokenize(tail))
+	}
+	r.finalize()
+
+	return r.String()
+}
+
+// StripANSI removes ANSI CSI and OSC sequences from s.
+func StripANSI(s string) string {
+	var b strings.Builder
+	for _, tok := range Tokenize(s) {
+		if tok.Type == TokenText {
+			b.WriteString(tok.Text)
+		}
+	}
+	return b.String()
+}
+
+// ANSIWidth returns the printable cell width of s with ANSI sequences ignored.
+func ANSIWidth(s string) int {
+	return tokensWidth(Tokenize(s))
+}
+
+// HasANSI reports whether s contains ANSI CSI or OSC sequences recognized by
+// Tokenize.
+func HasANSI(s string) bool {
+	for _, tok := range Tokenize(s) {
+		if tok.Type != TokenText {
+			return true
+		}
+	}
+	return false
+}
+
+func readCSI(s string, i int) (raw string, ok bool, next int) {
+	for j := i + len(csiPrefix); j < len(s); j++ {
+		if isCSIFinal(s[j]) {
+			return s[i : j+1], true, j + 1
+		}
+	}
+	return "", false, i
+}
+
+func isCSIFinal(b byte) bool {
+	return b >= 0x40 && b <= 0x7e
+}
+
+func csiToken(raw string) Token {
+	if len(raw) > len(csiPrefix) && raw[len(raw)-1] == sgrFinal {
+		params := raw[len(csiPrefix) : len(raw)-1]
+		if hasReset, _ := analyzeSGR(params); hasReset {
+			return Token{Type: TokenReset, Raw: raw}
+		}
+		return Token{Type: TokenSGR, Raw: raw}
+	}
+	return Token{Type: TokenSGR, Raw: raw}
+}
+
+func readOSC(s string, i int) (raw string, content string, ok bool, next int) {
+	for j := i + len(oscPrefix); j < len(s); j++ {
+		switch s[j] {
+		case bel:
+			return s[i : j+1], s[i+len(oscPrefix) : j], true, j + 1
+		case esc:
+			if j+1 < len(s) && s[j+1] == '\\' {
+				return s[i : j+2], s[i+len(oscPrefix) : j], true, j + 2
+			}
+		}
+	}
+	return "", "", false, i
+}
+
+func oscToken(raw, content string) Token {
+	if uri, ok := osc8URI(content); ok {
+		if uri == "" {
+			return Token{Type: TokenHyperlinkClose, Raw: raw}
+		}
+		return Token{Type: TokenHyperlinkOpen, Raw: raw}
+	}
+	return Token{Type: TokenSGR, Raw: raw}
+}
+
+func osc8URI(content string) (string, bool) {
+	if !strings.HasPrefix(content, "8;") {
+		return "", false
+	}
+	rest := content[2:]
+	idx := strings.IndexByte(rest, ';')
+	if idx < 0 {
+		return "", false
+	}
+	return rest[idx+1:], true
+}
+
+func tokensWidth(tokens []Token) int {
+	width := 0
+	for _, tok := range tokens {
+		if tok.Type == TokenText {
+			width += uniseg.StringWidth(tok.Text)
+		}
+	}
+	return width
+}
+
+func renderAll(tokens []Token, preserveResets bool) string {
+	r := &renderer{preserveResets: preserveResets}
+	r.writeTokens(tokens)
+	r.finalize()
+	return r.String()
+}
+
+func truncateOnly(s string, width int) string {
+	if width <= 0 {
+		return ""
+	}
+	tokens := Tokenize(s)
+	if tokensWidth(tokens) <= width {
+		return renderAll(tokens, false)
+	}
+	r := renderPrefix(tokens, width, false, false)
+	r.finalize()
+	return r.String()
+}
+
+func renderPrefix(tokens []Token, limit int, preserveResets bool, includeBoundaryANSI bool) *renderer {
+	r := &renderer{preserveResets: preserveResets}
+	visible := 0
+	for _, tok := range tokens {
"
}

{
  "returncode": 0,
  "output_head": "+	for _, tok := range tokens {
+		if tok.Type != TokenText {
+			if visible >= limit && !includeBoundaryANSI {
+				break
+			}
+			r.writeToken(tok)
+			continue
+		}
+
+		taken, used, complete := takeText(tok.Text, limit-visible)
+		if taken != "" {
+			r.writeText(taken)
+		}
+		visible += used
+		if !complete {
+			break
+		}
+	}
+	return r
+}
+
+func takeText(s string, width int) (taken string, used int, complete bool) {
+	if width < 0 {
+		width = 0
+	}
+
+	var b strings.Builder
+	state := -1
+	for len(s) > 0 {
+		cluster, rest, clusterWidth, newState := uniseg.FirstGraphemeClusterInString(s, state)
+		if cluster == "" {
+			break
+		}
+		if clusterWidth > width-used {
+			return b.String(), used, false
+		}
+		b.WriteString(cluster)
+		used += clusterWidth
+		s = rest
+		state = newState
+	}
+	return b.String(), used, true
+}
+
+type renderer struct {
+	b              strings.Builder
+	activeSGR      []string
+	pendingReopen  []string
+	hyperlinkOpen  bool
+	preserveResets bool
+}
+
+func (r *renderer) String() string {
+	return r.b.String()
+}
+
+func (r *renderer) writeTokens(tokens []Token) {
+	for _, tok := range tokens {
+		r.writeToken(tok)
+	}
+}
+
+func (r *renderer) writeToken(tok Token) {
+	if tok.Type == TokenReset {
+		r.writeReset(tok)
+		return
+	}
+
+	r.flushReopen()
+	r.b.WriteString(tok.Raw)
+
+	switch tok.Type {
+	case TokenSGR:
+		if raw := activeSGRRaw(tok.Raw); raw != "" {
+			r.activeSGR = append(r.activeSGR, raw)
+		}
+	case TokenHyperlinkOpen:
+		r.hyperlinkOpen = true
+	case TokenHyperlinkClose:
+		r.hyperlinkOpen = false
+	}
+}
+
+func (r *renderer) writeText(s string) {
+	r.flushReopen()
+	r.b.WriteString(s)
+}
+
+func (r *renderer) writeReset(tok Token) {
+	before := cloneStrings(r.activeSGR)
+	r.b.WriteString(tok.Raw)
+	activeAfter := activeSGRAfterReset(tok.Raw)
+
+	if r.preserveResets {
+		if len(r.pendingReopen) == 0 && len(before) > 0 {
+			r.pendingReopen = before
+		}
+		r.activeSGR = activeAfter
+		return
+	}
+
+	r.pendingReopen = nil
+	r.activeSGR = activeAfter
+}
+
+func (r *renderer) flushReopen() {
+	if len(r.pendingReopen) == 0 {
+		return
+	}
+	for _, raw := range r.pendingReopen {
+		r.b.WriteString(raw)
+	}
+	r.activeSGR = append(r.activeSGR, r.pendingReopen...)
+	r.pendingReopen = nil
+}
+
+func (r *renderer) finalize() {
+	if len(r.activeSGR) > 0 {
+		r.b.WriteString(sgrReset)
+		r.activeSGR = nil
+	}
+	if r.hyperlinkOpen {
+		r.b.WriteString(hyperlinkClose)
+		r.hyperlinkOpen = false
+	}
+}
+
+func cloneStrings(s []string) []string {
+	if len(s) == 0 {
+		return nil
+	}
+	clone := make([]string, len(s))
+	copy(clone, s)
+	return clone
+}
+
+func activeSGRRaw(raw string) string {
+	if !isSGR(raw) {
+		return ""
+	}
+	params := raw[len(csiPrefix) : len(raw)-1]
+	if hasReset, _ := analyzeSGR(params); hasReset {
+		return ""
+	}
+	return raw
+}
+
+func activeSGRAfterReset(raw string) []string {
+	if !isSGR(raw) {
+		return nil
+	}
+	params := raw[len(csiPrefix) : len(raw)-1]
+	_, activeParams := analyzeSGR(params)
+	if activeParams == "" {
+		return nil
+	}
+	return []string{csiPrefix + activeParams + string(sgrFinal)}
+}
+
+func isSGR(raw string) bool {
+	return strings.HasPrefix(raw, csiPrefix) && len(raw) > len(csiPrefix) && raw[len(raw)-1] == sgrFinal
+}
+
+func analyzeSGR(params string) (hasReset bool, activeAfter string) {
+	if params == "" {
+		return true, ""
+	}
+
+	fields := strings.Split(params, ";")
+	lastResetEnd := -1
+	for i := 0; i < len(fields); i++ {
+		field := fields[i]
+		if sgrFieldIsReset(field) {
+			hasReset = true
+			lastResetEnd = i + 1
+			continue
+		}
+
+		code, ok := sgrFieldCode(field)
+		if !ok || !isExtendedColorCode(code) || strings.Contains(field, ":") || i+1 >= len(fields) {
+			continue
+		}
+
+		mode, ok := sgrFieldCode(fields[i+1])
+		if !ok {
+			continue
+		}
+		switch mode {
+		case 2:
+			i += 4
+		case 5:
+			i += 2
+		}
+	}
+
+	if !hasReset || lastResetEnd >= len(fields) {
+		return hasReset, ""
+	}
+	return hasReset, strings.Join(fields[lastResetEnd:], ";")
+}
+
+func sgrFieldIsReset(field string) bool {
+	code, ok := sgrFieldCode(field)
+	return ok && code == 0
+}
+
+func sgrFieldCode(field string) (int, bool) {
+	if idx := strings.IndexByte(field, ':'); idx >= 0 {
+		field = field[:idx]
+	}
+	if field == "" {
+		return 0, true
+	}
+	code, err := strconv.Atoi(field)
+	if err != nil {
+		return 0, false
+	}
+	return code, true
+}
+
+func isExtendedColorCode(code int) bool {
+	switch code {
+	case 38, 48, 58:
+		return true
+	default:
+		return false
+	}
+}
