import type * as symbols from '../internals/symbols';
import type { Pattern, MatchedValue } from './Pattern';
import type { InvertPatternForExclude, InvertPattern } from './InvertPattern';
import type { DeepExclude } from './DeepExclude';
import type { Union, GuardValue, IsNever } from './helpers';
import type { FindSelected } from './FindSelected';
import type { PickReturnValue } from './Match';

interface NonExhaustiveError<i> {
  __nonExhaustive: never;
}

interface TSPatternError<i> {
  __nonExhaustive: never;
}

/**
 * #### MatchEach
 * An interface to create a pattern matching expression that evaluates every
 * matching clause and returns all matching handler results.
 */
export type MatchEach<
  input,
  currentInput,
  remaining,
  output,
  handledCases extends any[] = [],
  inferredOutput = never
> = {
  /**
   * `.with(pattern, handler)` Registers a pattern and an handler function that
   * will be called if the pattern matches the input value.
   **/
  with<
    const p extends Pattern<currentInput>,
    c,
    value extends MatchedValue<currentInput, InvertPattern<p, currentInput>>
  >(
    pattern: IsNever<p> extends true
      ? /**
         * HACK: Using `IsNever<p>` here is a hack to make sure the type checker
         * forwards the input type parameter to pattern creator functions like
         * `P.when`, `P.not` and `P.union` when they are passed to `.with`
         * directly.
         */
        Pattern<currentInput>
      : p,
    handler: (
      selections: FindSelected<value, p>,
      value: value
    ) => PickReturnValue<output, c>
  ): InvertPatternForExclude<p, value> extends infer excluded
    ? MatchEach<
        input,
        currentInput,
        Exclude<remaining, excluded>,
        output,
        [...handledCases, excluded],
        Union<inferredOutput, c>
      >
    : never;

  with<
    const p1 extends Pattern<currentInput>,
    const p2 extends Pattern<currentInput>,
    c,
    p extends p1 | p2,
    value extends p extends any
      ? MatchedValue<currentInput, InvertPattern<p, currentInput>>
      : never
  >(
    p1: p1,
    p2: p2,
    handler: (value: value) => PickReturnValue<output, c>
  ): [
    InvertPatternForExclude<p1, value>,
    InvertPatternForExclude<p2, value>
  ] extends [infer excluded1, infer excluded2]
    ? MatchEach<
        input,
        currentInput,
        Exclude<remaining, excluded1 | excluded2>,
        output,
        [...handledCases, excluded1, excluded2],
        Union<inferredOutput, c>
      >
    : never;

  with<
    const p1 extends Pattern<currentInput>,
    const p2 extends Pattern<currentInput>,
    const p3 extends Pattern<currentInput>,
    const ps extends readonly Pattern<currentInput>[],
    c,
    p extends p1 | p2 | p3 | ps[number],
    value extends MatchedValue<currentInput, InvertPattern<p, currentInput>>
  >(
    ...args: [
      p1: p1,
      p2: p2,
      p3: p3,
      ...patterns: ps,
      handler: (value: value) => PickReturnValue<output, c>
    ]
  ): [
    InvertPatternForExclude<p1, value>,
    InvertPatternForExclude<p2, value>,
    InvertPatternForExclude<p3, value>,
    MakeTuples<ps, value>
  ] extends [
    infer excluded1,
    infer excluded2,
    infer excluded3,
    infer excludedRest
  ]
    ? MatchEach<
        input,
        currentInput,
        Exclude<
          remaining,
          | excluded1
          | excluded2
          | excluded3
          | Extract<excludedRest, any[]>[number]
        >,
        output,
        [
          ...handledCases,
          excluded1,
          excluded2,
          excluded3,
          ...Extract<excludedRest, any[]>
        ],
        Union<inferredOutput, c>
      >
    : never;

  with<
    const pat extends Pattern<currentInput>,
    pred extends (
      value: MatchedValue<currentInput, InvertPattern<pat, currentInput>>
    ) => unknown,
    c,
    value extends GuardValue<pred>
  >(
    pattern: pat,
    predicate: pred,
    handler: (
      selections: FindSelected<value, pat>,
      value: value
    ) => PickReturnValue<output, c>
  ): pred extends (value: any) => value is infer narrowed
    ? MatchEach<
        input,
        currentInput,
        Exclude<remaining, narrowed>,
        output,
        [...handledCases, narrowed],
        Union<inferredOutput, c>
      >
    : MatchEach<
        input,
        currentInput,
        remaining,
        output,
        handledCases,
        Union<inferredOutput, c>
      >;

  /**
   * `.when(predicate, handler)` Registers a predicate function and an handler
   * function. If the predicate returns true, the handler function will be called.
   **/
  when<
    pred extends (value: currentInput) => unknown,
    c,
    value extends GuardValue<pred>
  >(
    predicate: pred,
    handler: (value: value) => PickReturnValue<output, c>
  ): pred extends (value: any) => value is infer narrowed
    ? MatchEach<
        input,
        currentInput,
        Exclude<remaining, narrowed>,
        output,
        [...handledCases, narrowed],
        Union<inferredOutput, c>
      >
    : MatchEach<
        input,
        currentInput,
        remaining,
        output,
        handledCases,
        Union<inferredOutput, c>
      >;

  /**
   * `.tap(callback)` Registers a side-effect callback. When the expression is
   * evaluated, this tap point calls its callback once for every result that has
   * already been collected at this point in declaration order.
   */
  tap(
    callback: (result: PickReturnValue<output, inferredOutput>, value: input) => void
  ): MatchEach<input, currentInput, remaining, output, handledCases, inferredOutput>;

  /**
   * `.otherwise()` takes a default handler function that will be called if no
   * previous pattern matched your input.
   */
  otherwise<c>(
    handler: (value: DeepExcludeAll<remaining, handledCases>) => PickReturnValue<
      output,
      c
    >
  ): PickReturnValue<output, Union<inferredOutput, c>>[];

  /**
   * `.exhaustive()` checks that all cases are handled, and returns every
   * matching result.
   */
  exhaustive: DeepExcludeAll<remaining, handledCases> extends infer remainingCases
    ? [remainingCases] extends [never]
      ? Exhaustive<output, inferredOutput>
      : NonExhaustiveError<remainingCases>
    : never;

  /**
   * `.run()` returns every matching result.
   *
   * ⚠️ calling this function is unsafe, and may throw if no pattern matches your input.
   */
  run(): PickReturnValue<output, inferredOutput>[];

  /**
   * `.returnType<T>()` Lets you specify the return type for all of your branches.
   */
  returnType: [inferredOutput] extends [never]
    ? <newOutput>() => MatchEach<
        input,
        currentInput,
        remaining,
        newOutput,
        handledCases
      >
    : TSPatternError<'calling `.returnType<T>()` is only allowed directly after `matchEach(...)`.'>;

  /**
   * `.narrow()` narrows subsequent patterns to exclude all cases that have
   * previously been handled.
   */
  narrow(): DeepExcludeAll<remaining, handledCases> extends infer narrowed
    ? MatchEach<input, narrowed, narrowed, output, [], inferredOutput>
    : never;

  /**
   * `.toFunction()` compiles this matcher into a reusable function. The
   * returned function throws if no pattern matches its input.
   */
  toFunction(): (input: input) => PickReturnValue<output, inferredOutput>[];

  /**
   * `.toExhaustiveFunction()` compiles this matcher into a reusable function,
   * while enforcing compile-time exhaustiveness.
   */
  toExhaustiveFunction: DeepExcludeAll<
    remaining,
    handledCases
  > extends infer remainingCases
    ? [remainingCases] extends [never]
      ? () => (input: input) => PickReturnValue<output, inferredOutput>[]
      : NonExhaustiveError<remainingCases>
    : never;

  /**
   * `.toPartialFunction()` compiles this matcher into a reusable partial
   * function. The returned function returns undefined if no pattern matches.
   */
  toPartialFunction(): (
    input: input
  ) => PickReturnValue<output, inferredOutput>[] | undefined;
};

type DeepExcludeAll<a, tupleList extends any[]> = [a] extends [never]
  ? never
  : tupleList extends [infer excluded, ...infer tail]
  ? DeepExcludeAll<DeepExclude<a, excluded>, tail>
  : a;

type MakeTuples<ps extends readonly any[], value> = {
  -readonly [index in keyof ps]: InvertPatternForExclude<ps[index], value>;
};

/**
 * The type of an overloaded function for `.exhaustive`, permitting calling it
 * with or without a catch-all handler function.
 */
type Exhaustive<output, inferredOutput> = {
  /**
   * `.exhaustive()` checks that all cases are handled, and returns every
   * matching result.
   */
  (): PickReturnValue<output, inferredOutput>[];
  /**
   * `.exhaustive(fallback)` checks that all cases are handled and returns every
   * matching result. If no pattern matches at runtime, the fallback value is
   * returned in a single-element array.
   */
  <otherOutput>(
    handler: (unexpectedValue: unknown) => PickReturnValue<output, otherOutput>
  ): PickReturnValue<output, Union<inferredOutput, otherOutput>>[];
};
