import { Pattern } from './types/Pattern';
import { MatchEach } from './types/MatchEach';
import * as symbols from './internals/symbols';
import { matchPattern } from './internals/helpers';
import { NonExhaustiveError } from './errors';

type WithClause<input, output> = {
  type: 'with';
  patterns: Pattern<input>[];
  predicate: ((value: input) => unknown) | undefined;
  handler: (selection: unknown, value: input) => output;
};

type WhenClause<input, output> = {
  type: 'when';
  predicate: (value: input) => unknown;
  handler: (selection: input, value: input) => output;
};

type Tap<input, output> = {
  type: 'tap';
  callback: (result: output, value: input) => void;
};

type MatchEachStep<input, output> =
  | WithClause<input, output>
  | WhenClause<input, output>
  | Tap<input, output>;

type PatternSelection = {
  matched: boolean;
  value: unknown;
};

/**
 * `matchEach` creates a pattern matching expression that evaluates every
 * matching clause instead of short-circuiting on the first match.
 *
 * Use `.with(pattern, handler)` to register clauses and `.run()`,
 * `.exhaustive()` or `.otherwise(handler)` to evaluate the expression and get
 * an array of every matching handler result in declaration order.
 */
export function matchEach<const input, output = symbols.unset>(
  value: input
): MatchEach<input, input, input, output>;
export function matchEach<input, output = symbols.unset>(): MatchEach<
  input,
  input,
  input,
  output
>;
export function matchEach(value?: unknown): MatchEach<unknown, unknown, unknown, symbols.unset> {
  return new MatchEachExpression(value, arguments.length > 0, []) as any;
}

/**
 * This class represents a matchEach expression. It follows the builder pattern,
 * accumulating clauses until an evaluation or compilation method is called.
 *
 * The types of this class aren't public; the public type definition can be
 * found in src/types/MatchEach.ts.
 */
class MatchEachExpression<input, output> {
  constructor(
    private input: input,
    private hasInput: boolean,
    private steps: MatchEachStep<input, output>[]
  ) {}

  with(...args: any[]): MatchEachExpression<input, output> {
    const handler: (selection: unknown, value: input) => output =
      args[args.length - 1];

    const patterns: Pattern<input>[] = [args[0]];
    let predicate: ((value: input) => unknown) | undefined = undefined;

    if (args.length === 3 && typeof args[1] === 'function') {
      // case with guard as second argument
      predicate = args[1];
    } else if (args.length > 2) {
      // case with several patterns
      patterns.push(...args.slice(1, args.length - 1));
    }

    return new MatchEachExpression(this.input, this.hasInput, [
      ...this.steps,
      { type: 'with', patterns, predicate, handler },
    ]);
  }

  when(
    predicate: (value: input) => unknown,
    handler: (selection: input, value: input) => output
  ): MatchEachExpression<input, output> {
    return new MatchEachExpression(this.input, this.hasInput, [
      ...this.steps,
      { type: 'when', predicate, handler },
    ]);
  }

  tap(
    callback: (result: output, value: input) => void
  ): MatchEachExpression<input, output> {
    return new MatchEachExpression(this.input, this.hasInput, [
      ...this.steps,
      { type: 'tap', callback },
    ]);
  }

  otherwise(handler: (value: input) => output): output[] {
    const results = this.evaluate(this.input);
    return results.length > 0 ? results : [handler(this.input)];
  }

  exhaustive(unexpectedValueHandler?: (input: unknown) => output): output[] {
    const results = this.evaluate(this.input);
    if (results.length > 0) return results;
    if (unexpectedValueHandler) return [unexpectedValueHandler(this.input)];
    return defaultCatcher(this.input);
  }

  run(): output[] {
    return this.exhaustive();
  }

  returnType() {
    return this;
  }

  narrow() {
    return this;
  }

  toFunction(): (input: input) => output[] {
    return (input: input) => {
      const results = this.evaluate(input);
      if (results.length === 0) return defaultCatcher(input);
      return results;
    };
  }

  toExhaustiveFunction(): (input: input) => output[] {
    return this.toFunction();
  }

  toPartialFunction(): (input: input) => output[] | undefined {
    return (input: input) => {
      const results = this.evaluate(input);
      return results.length > 0 ? results : undefined;
    };
  }

  private evaluate(input: input): output[] {
    const results: output[] = [];

    for (const step of this.steps) {
      if (step.type === 'tap') {
        results.forEach((result) => step.callback(result, input));
        continue;
      }

      if (step.type === 'when') {
        if (Boolean(step.predicate(input))) {
          results.push(step.handler(input, input));
        }
        continue;
      }

      const patternSelection = matchPatterns(step.patterns, input);
      const matched =
        patternSelection.matched &&
        (step.predicate ? Boolean(step.predicate(input)) : true);

      if (matched) {
        results.push(step.handler(patternSelection.value, input));
      }
    }

    return results;
  }
}

function matchPatterns<input>(
  patterns: Pattern<input>[],
  input: input
): PatternSelection {
  for (const pattern of patterns) {
    const patternSelection = matchPatternWithSelection(pattern, input);
    if (patternSelection.matched) return patternSelection;
  }

  return { matched: false, value: undefined };
}

function matchPatternWithSelection<input>(
  pattern: Pattern<input>,
  input: input
): PatternSelection {
  let hasSelections = false;
  const selected: Record<string, unknown> = {};
  const select = (key: string, value: unknown) => {
    hasSelections = true;
    selected[key] = value;
  };

  const matched = matchPattern(pattern, input, select);

  if (!matched) return { matched: false, value: undefined };

  const selections = hasSelections
    ? symbols.anonymousSelectKey in selected
      ? selected[symbols.anonymousSelectKey]
      : selected
    : input;

  return { matched: true, value: selections };
}

function defaultCatcher(input: unknown): never {
  throw new NonExhaustiveError(input);
}
