import { Equal, Expect } from '../src/types/helpers';

describe('matchEach', () => {
  it('evaluates every matching pattern and returns results in declaration order', () => {
    const result = matchEach(2)
      .with(P.number, () => 'number')
      .with(P.when((x: number) => x % 2 === 0), () => 'even')
      .with(2, () => 'two')
      .with(3, () => 'three')
      .run();

    expect(result).toEqual(['number', 'even', 'two']);
  });

