    const result = matchEach<'a' | 'b' | 'c'>('b')
      .with('a', 'b', (x) => `letter:${x}`)
      .with(
        P._,
        (x): x is 'b' => x === 'b',
        (x) => `guard:${x}`
      )
      .with('c', () => 'c')
      .run();

    type t = Expect<Equal<typeof result, string[]>>;
    expect(result).toEqual(['letter:b', 'guard:b']);
  });

