package pebble

import (
	"context"
	"sync"
	"sync/atomic"
	"time"

	"github.com/cockroachdb/errors"
	"github.com/cockroachdb/pebble/internal/base"
)

var (
	// ErrDurabilityJobExpired is returned by WaitForJobDurability when the job
	// is older than the bounded retention window maintained for durable commit
	// jobs.
	ErrDurabilityJobExpired = errors.New("pebble: durability job expired")
	// ErrDurabilityJobUnknown is returned by WaitForJobDurability when the job
	// was never registered as a durable commit job.
	ErrDurabilityJobUnknown = errors.New("pebble: durability job unknown")
	// ErrDurabilityNotifyLimit is delivered by DurabilityNotify when too many
	// outstanding durability subscriptions are already registered.
	ErrDurabilityNotifyLimit = errors.New("pebble: durability notification limit exceeded")
)

const (
	durabilityJobRetention  = 8192
	durabilityNotifyLimit   = 4096
	minimumNonZeroDuration = time.Nanosecond
)

// DurabilityStats contains a snapshot of durability tracking state.
type DurabilityStats struct {
	HighestDurableSeqNum  base.SeqNum
	FirstErr              error
	PendingWaiters        int64
	TotalDurableCommits   uint64
	TotalFailedCommits    uint64
	CumulativeSyncDuration time.Duration
	MaxSyncDuration        time.Duration
}

type durabilitySeqWaiter struct {
	seq    base.SeqNum
	ch     chan error
	notify bool
	done   bool
}

type durabilityJob struct {
	id       int
	doneCh   chan struct{}
	done     bool
	err      error
	expired  bool
}

type durabilityTracker struct {
	metricsEnabled bool
	pendingWaiters atomic.Int64

	mu struct {
		sync.Mutex
		highestDurable base.SeqNum
		firstErr       error

		waiters      []*durabilitySeqWaiter
		pendingNotify int

		jobs           map[int]*durabilityJob
		jobOrder       []int
		expiredThrough int
		maxJobID       int

		totalDurableCommits    uint64
		totalFailedCommits     uint64
		cumulativeSyncDuration time.Duration
		maxSyncDuration        time.Duration

		metricDurableCommitCount    uint64
		metricDurableCommitDuration time.Duration
	}
}

func (t *durabilityTracker) init(metricsEnabled bool) {
	t.metricsEnabled = metricsEnabled
}

func (t *durabilityTracker) newCommit(d *DB, jobID int, correlationID uint64) *durableCommit {
	t.registerJob(jobID)
	return &durableCommit{
		db: d,
		info: BatchDurableInfo{
			JobID:         jobID,
			CorrelationID: correlationID,
		},
	}
}

func (t *durabilityTracker) registerJob(jobID int) {
	if jobID == 0 {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.mu.jobs == nil {
		t.mu.jobs = make(map[int]*durabilityJob)
	}
	if jobID > t.mu.maxJobID {
		t.mu.maxJobID = jobID
	}
	if _, ok := t.mu.jobs[jobID]; ok {
		return
	}
	j := &durabilityJob{id: jobID, doneCh: make(chan struct{})}
	t.mu.jobs[jobID] = j
	t.mu.jobOrder = append(t.mu.jobOrder, jobID)
	for len(t.mu.jobOrder) > durabilityJobRetention {
		oldID := t.mu.jobOrder[0]
		copy(t.mu.jobOrder, t.mu.jobOrder[1:])
		t.mu.jobOrder = t.mu.jobOrder[:len(t.mu.jobOrder)-1]
		if oldID > t.mu.expiredThrough {
			t.mu.expiredThrough = oldID
		}
		if old := t.mu.jobs[oldID]; old != nil {
			delete(t.mu.jobs, oldID)
			if !old.done {
				old.done = true
				old.expired = true
				old.err = ErrDurabilityJobExpired
				close(old.doneCh)
			}
		}
	}
}

func (t *durabilityTracker) completeCommit(info BatchDurableInfo) {
	t.mu.Lock()
	if info.Err != nil {
		t.mu.totalFailedCommits++
		if t.mu.firstErr == nil {
			t.mu.firstErr = info.Err
		}
		t.failPendingJobsLocked(info.Err)
	} else {
		t.mu.totalDurableCommits++
		if info.KeyCount > 0 {
			endSeq := info.SeqNum + base.SeqNum(info.KeyCount) - 1
			if endSeq > t.mu.highestDurable {
				t.mu.highestDurable = endSeq
			}
		}
		t.mu.cumulativeSyncDuration += info.SyncDuration
		if info.SyncDuration > t.mu.maxSyncDuration {
			t.mu.maxSyncDuration = info.SyncDuration
		}
		if t.metricsEnabled {
			t.mu.metricDurableCommitCount++
			t.mu.metricDurableCommitDuration += info.SyncDuration
		}
	}
	t.completeJobLocked(info.JobID, info.Err)
	t.wakeSeqWaitersLocked()
	t.mu.Unlock()
}

func (t *durabilityTracker) failPendingJobsLocked(err error) {
	for _, j := range t.mu.jobs {
		if !j.done {
			j.done = true
			j.err = err
			close(j.doneCh)
		}
	}
}

func (t *durabilityTracker) completeJobLocked(jobID int, err error) {
	if jobID == 0 || t.mu.jobs == nil {
		return
	}
	j := t.mu.jobs[jobID]
	if j == nil || j.done {
		return
	}
	j.done = true
	j.err = err
	close(j.doneCh)
}

func (t *durabilityTracker) close(err error) {
	if err == nil {
		err = errors.WithStack(ErrClosed)
	}
	t.mu.Lock()
	if t.mu.firstErr == nil {
		t.mu.firstErr = err
	}
	t.failPendingJobsLocked(err)
	t.wakeSeqWaitersLocked()
	t.mu.Unlock()
}

func (t *durabilityTracker) seqResultLocked(seq base.SeqNum) (error, bool) {
	if seq == 0 {
		if t.mu.totalDurableCommits > 0 {
			return nil, true
		}
		if t.mu.firstErr != nil {
			return t.mu.firstErr, true
		}
		return nil, false
	}
	if seq <= t.mu.highestDurable {
		return nil, true
	}
	if t.mu.firstErr != nil {
		return t.mu.firstErr, true
	}
	return nil, false
}

func (t *durabilityTracker) wakeSeqWaitersLocked() {
	if len(t.mu.waiters) == 0 {
		return
	}
	remaining := t.mu.waiters[:0]
	for _, w := range t.mu.waiters {
		if w.done {
			continue
		}
		if err, ok := t.seqResultLocked(w.seq); ok {
			w.done = true
			if w.notify {
				t.mu.pendingNotify--
			}
			w.ch <- err
			continue
		}
		remaining = append(remaining, w)
	}
	clear(t.mu.waiters[len(remaining):])
	t.mu.waiters = remaining
}

func readyDurabilityChan(err error) <-chan error {
	ch := make(chan error, 1)
	ch <- err
	return ch
}

func (t *durabilityTracker) waitSeq(ctx context.Context, seq base.SeqNum) error {
	if ctx == nil {
		panic("pebble: nil context")
	}
	t.mu.Lock()
	if err, ok := t.seqResultLocked(seq); ok {
		t.mu.Unlock()
		return err
	}
	w := &durabilitySeqWaiter{seq: seq, ch: make(chan error, 1)}
	t.mu.waiters = append(t.mu.waiters, w)
	t.pendingWaiters.Add(1)
	t.mu.Unlock()
	defer t.pendingWaiters.Add(-1)

	select {
	case err := <-w.ch:
		return err
	case <-ctx.Done():
		t.mu.Lock()
		select {
		case err := <-w.ch:
			t.mu.Unlock()
			return err
		default:
		}
		if err, ok := t.seqResultLocked(seq); ok {
			t.mu.Unlock()
			return err
		}
		w.done = true
		t.mu.Unlock()
		return ctx.Err()
	}
}

func (t *durabilityTracker) notify(seq base.SeqNum) <-chan error {
	t.mu.Lock()
	defer t.mu.Unlock()
	if err, ok := t.seqResultLocked(seq); ok {
		return readyDurabilityChan(err)
	}
	if t.mu.pendingNotify >= durabilityNotifyLimit {
		return readyDurabilityChan(ErrDurabilityNotifyLimit)
	}
	w := &durabilitySeqWaiter{seq: seq, ch: make(chan error, 1), notify: true}
	t.mu.pendingNotify++
	t.mu.waiters = append(t.mu.waiters, w)
	return w.ch
}

func (t *durabilityTracker) waitJob(ctx context.Context, jobID int) error {
	if ctx == nil {
		panic("pebble: nil context")
	}
	if jobID == 0 {
		return ErrDurabilityJobUnknown
	}
	t.mu.Lock()
	j := t.mu.jobs[jobID]
	if j == nil {
		err := ErrDurabilityJobUnknown
		if jobID <= t.mu.expiredThrough {
			err = ErrDurabilityJobExpired
		}
		t.mu.Unlock()
		return err
	}
	if j.done {
		err := j.err
		t.mu.Unlock()
		return err
	}
	doneCh := j.doneCh
	t.pendingWaiters.Add(1)
	t.mu.Unlock()
	defer t.pendingWaiters.Add(-1)

	select {
	case <-doneCh:
		return j.err
	case <-ctx.Done():
		t.mu.Lock()
		if j.done {
			err := j.err
			t.mu.Unlock()
			return err
		}
		if t.mu.firstErr != nil {
			err := t.mu.firstErr
			t.mu.Unlock()
			return err
		}
		t.mu.Unlock()
		return ctx.Err()
	}
}

func (t *durabilityTracker) state() (base.SeqNum, error) {
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.mu.highestDurable, t.mu.firstErr
}

func (t *durabilityTracker) stats() DurabilityStats {
	t.mu.Lock()
	defer t.mu.Unlock()
	return DurabilityStats{
		HighestDurableSeqNum:  t.mu.highestDurable,
		FirstErr:              t.mu.firstErr,
		PendingWaiters:        t.pendingWaiters.Load(),
		TotalDurableCommits:   t.mu.totalDurableCommits,
		TotalFailedCommits:    t.mu.totalFailedCommits,
		CumulativeSyncDuration: t.mu.cumulativeSyncDuration,
		MaxSyncDuration:        t.mu.maxSyncDuration,
	}
}

func (t *durabilityTracker) metrics() (uint64, time.Duration) {
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.mu.metricDurableCommitCount, t.mu.metricDurableCommitDuration
}

type durableCommit struct {
	db   *DB
	info BatchDurableInfo

	syncErr      error
	syncDuration time.Duration
	syncRecorded atomic.Bool

	completeOnce sync.Once
}

func (c *durableCommit) recordSync(err error, syncDuration time.Duration) {
	c.syncErr = err
	c.syncDuration = syncDuration
	c.syncRecorded.Store(true)
}

func (c *durableCommit) complete() {
	c.completeOnce.Do(func() {
		info := c.info
		info.Err = c.syncErr
		info.SyncDuration = c.syncDuration
		if info.Err == nil {
			if info.ApplyDuration <= 0 {
				info.ApplyDuration = minimumNonZeroDuration
			}
			if info.SyncDuration <= 0 {
				info.SyncDuration = minimumNonZeroDuration
			}
		}
		c.db.durability.completeCommit(info)
		c.db.opts.EventListener.BatchDurable(info)
	})
}

// WaitForDurability blocks until seqNum is durable. A seqNum of zero blocks
// until any successful sync commit is durable. If the WAL is disabled, it
// returns nil immediately.
func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
	return d.WaitForDurabilityContext(context.Background(), seqNum)
}

// WaitForDurabilityContext is like WaitForDurability, with cancellation through
// ctx. Durability and close errors take precedence over context cancellation.
func (d *DB) WaitForDurabilityContext(ctx context.Context, seqNum base.SeqNum) error {
	if d.opts.DisableWAL {
		return nil
	}
	return d.durability.waitSeq(ctx, seqNum)
}

// WaitForDurabilityBatch blocks until every sequence number in seqNums is
// durable. A nil or empty slice returns nil immediately. If the WAL is disabled,
// it returns nil immediately.
func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
	return d.WaitForDurabilityBatchContext(context.Background(), seqNums)
}

// WaitForDurabilityBatchContext is like WaitForDurabilityBatch, with
// cancellation through ctx. Durability and close errors take precedence over
// context cancellation.
func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqNums []base.SeqNum) error {
	if d.opts.DisableWAL || len(seqNums) == 0 {
		return nil
	}
	maxSeq := seqNums[0]
	for _, seq := range seqNums[1:] {
		if seq > maxSeq {
			maxSeq = seq
		}
	}
	return d.durability.waitSeq(ctx, maxSeq)
}

// WaitForJobDurability waits for the durable commit job with the provided job
// ID. Job IDs outside the bounded retention window return
// ErrDurabilityJobExpired. Job IDs that were never registered return
// ErrDurabilityJobUnknown. If the WAL is disabled, it returns nil immediately.
func (d *DB) WaitForJobDurability(jobID int) error {
	return d.WaitForJobDurabilityContext(context.Background(), jobID)
}

// WaitForJobDurabilityContext is like WaitForJobDurability, with cancellation
// through ctx. Durability and close errors take precedence over context
// cancellation.
func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
	if d.opts.DisableWAL {
		return nil
	}
	return d.durability.waitJob(ctx, jobID)
}

// DurableState returns the highest durable sequence number observed by this DB
// instance and the first latched durability or close error, if any.
func (d *DB) DurableState() (base.SeqNum, error) {
	if d.opts.DisableWAL {
		return 0, nil
	}
	return d.durability.state()
}

// DurabilityNotify returns a receive-only channel that receives nil when seqNum
// is durable, or a non-nil error on WAL sync failure or DB close. If too many
// durability subscriptions are outstanding, the returned channel receives
// ErrDurabilityNotifyLimit immediately. If the WAL is disabled, the returned
// channel receives nil immediately.
func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
	if d.opts.DisableWAL {
		return readyDurabilityChan(nil)
	}
	return d.durability.notify(seqNum)
}

// DurabilityStats returns a snapshot of durability tracking statistics.
func (d *DB) DurabilityStats() DurabilityStats {
	if d.opts.DisableWAL {
		return DurabilityStats{}
	}
	return d.durability.stats()
}
